// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./Identity.sol";
import "./ICertificateValidator.sol";

contract Certificates is ReentrancyGuard {
    Identity public identityContract;

    struct Certificate {
        address student;
        address institution;
        string ipfsHash;
        uint256 issuedAt;
        bool isValid;
    }

    struct CertificateInfo {
        bytes32 certificate;
        string ipfsHash;
        bool exist;
    }

    mapping(bytes32 => Certificate) public certificates;
    mapping(address => CertificateInfo[]) public userCertificates;

    event CertificateIssued(bytes32 indexed certificateId, address indexed student, address indexed institution);
    event CertificateRevoked(bytes32 indexed certificateId);
    event ValidationContractUpdated(address indexed previousContract, address indexed newContract, address indexed updatedBy);

    address public validationContract;

    constructor(address _identityContract) {
        identityContract = Identity(_identityContract);
    }

    modifier onlyVerifiedInstitution() {
        require(
            identityContract.getUserRole(msg.sender) == Identity.UserRole.INSTITUTION &&
            identityContract.isVerifiedUser(msg.sender),
            "Not a verified institution Or user is not Institution"
        );
        _;
    }

    modifier withValidation(address _student, string memory _ipfsHash) {
        if (validationContract != address(0)) {
            (bool allowed, string memory reason) = ICertificateValidator(validationContract)
                .validateIssuance(msg.sender, _student, _ipfsHash);
            require(allowed, reason);
        }
        _;
    }

    function issueCertificate(
        address _student,
        string memory _ipfsHash
    ) external onlyVerifiedInstitution nonReentrant withValidation(_student, _ipfsHash) returns (bytes32) {
        require(identityContract.getUserRole(_student) == Identity.UserRole.STUDENT, "The address you are trying to give the certificate is not a student address.");
        require(bytes(_ipfsHash).length > 0, "Invalid IPFS hash");

        bytes32 certificateId = keccak256(
            abi.encodePacked(_student, msg.sender, _ipfsHash, block.timestamp)
        );

        require(certificates[certificateId].issuedAt == 0, "Certificate already exists");

        certificates[certificateId] = Certificate(
            _student,
            msg.sender,
            _ipfsHash,
            block.timestamp,
            true
        );

        userCertificates[_student].push(CertificateInfo({
            certificate: certificateId,
            ipfsHash: _ipfsHash,
            exist: true
        }));
        userCertificates[msg.sender].push(CertificateInfo({
            certificate: certificateId,
            ipfsHash: _ipfsHash,
            exist: true
        }));

        emit CertificateIssued(certificateId, _student, msg.sender);

        return certificateId;
    }

    function revokeCertificate(bytes32 _certificateId) external nonReentrant {
        Certificate storage cert = certificates[_certificateId];
        require(cert.issuedAt > 0, "Certificate does not exist");
        require(cert.institution == msg.sender, "Not certificate issuer");
        require(cert.isValid, "Certificate already revoked");

        cert.isValid = false;
        emit CertificateRevoked(_certificateId);
    }

    function verifyCertificate(bytes32 _certificateId) external view returns (
        address student,
        address institution,
        string memory ipfsHash,
        uint256 issuedAt,
        bool isValid
    ) {
        Certificate memory cert = certificates[_certificateId];
        require(cert.issuedAt > 0, "Certificate does not exist");

        return (
            cert.student,
            cert.institution,
            cert.ipfsHash,
            cert.issuedAt,
            cert.isValid
        );
    }

    function getUserCertificates(address _user) external view returns (CertificateInfo[] memory) {
        return userCertificates[_user];
    }

    function setValidationContract(address _validationContract) external {
        require(
            identityContract.getUserRole(msg.sender) == Identity.UserRole.ADMIN ||
            msg.sender == identityContract.owner(),
            "Not an admin"
        );
        require(_validationContract == address(0) || _validationContract.code.length > 0, "Validator must be a contract");
        address previousContract = validationContract;
        validationContract = _validationContract;
        emit ValidationContractUpdated(previousContract, _validationContract, msg.sender);
    }
}

contracts/CourseManagement.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "./Identity.sol";

contract CourseManagement is Ownable, Pausable {
    Identity public identityContract;

    struct Course {
        string courseId;
        string name;
        uint256 credits;
        string department;
        bool isActive;
        uint256 creationDate;
    }

    struct CourseOffering {
        string semester;
        string doctorName;
        uint256 examDate;
        string bookTitle;
        bool isAvailableForEnrollment;
    }

    // Course data
    mapping(string => Course) public courses;
    mapping(string => mapping(string => CourseOffering)) public courseOfferings;
    mapping(string => string[]) public courseOfferingTerms;
    mapping(string => string[]) public departmentCourses;

    string public currentActiveSemester;
    string[] private departmentNames;
    mapping(string => bool) private departments;

    // Events
    event CourseAdded(string indexed courseId, string name, string department);
    event CourseDetailsUpdated(string indexed courseId, string name, uint256 credits, string department);
    event CourseDeactivated(string indexed courseId);
    event CourseOfferingAdded(string indexed courseId, string indexed semester, string doctorName);
    event CourseOfferingUpdated(
        string indexed courseId,
        string indexed semester,
        string doctorName,
        uint256 examDate,
        string bookTitle
    );
    event CurrentActiveSemesterUpdated(string oldSemester, string newSemester);
    event DepartmentAdded(string departmentName);

    modifier onlyVerifiedInstitution() {
        require(
            identityContract.isVerifiedUser(msg.sender) &&
            identityContract.getUserRole(msg.sender) == Identity.UserRole.INSTITUTION,
            "Not a verified institution"
        );
        _;
    }

    constructor(address _identityContractAddress) {
        require(_identityContractAddress != address(0), "Invalid identity contract address");
        identityContract = Identity(_identityContractAddress);
    }

    function addCourse(
        string memory _courseId,
        string memory _name,
        uint256 _credits,
        string memory _department
    ) external onlyVerifiedInstitution {
        require(bytes(_courseId).length > 0, "Course ID cannot be empty");
        require(bytes(_name).length > 0, "Course name cannot be empty");
        require(bytes(_department).length > 0, "Department cannot be empty");
        require(courses[_courseId].creationDate == 0, "Course already exists");
        require(departments[_department], "Department does not exist");

        courses[_courseId] = Course({
            courseId: _courseId,
            name: _name,
            credits: _credits,
            department: _department,
            isActive: true,
            creationDate: block.timestamp
        });

        departmentCourses[_department].push(_courseId);
        emit CourseAdded(_courseId, _name, _department);
    }

    function addDepartment(string memory _departmentName) external onlyVerifiedInstitution {
        require(bytes(_departmentName).length > 0, "Department name cannot be empty");
        require(!departments[_departmentName], "Department already exists");

        departments[_departmentName] = true;
        departmentNames.push(_departmentName);
        emit DepartmentAdded(_departmentName);
    }

    function updateCourseStaticDetails(
        string memory _courseId,
        string memory _newName,
        uint256 _newCredits,
        string memory _newDepartment
    ) external onlyVerifiedInstitution {
        require(courses[_courseId].creationDate > 0, "Course does not exist");
        require(bytes(_newName).length > 0, "Course name cannot be empty");
        require(departments[_newDepartment], "Department does not exist");

        Course storage course = courses[_courseId];
        course.name = _newName;
        course.credits = _newCredits;
        course.department = _newDepartment;

        emit CourseDetailsUpdated(_courseId, _newName, _newCredits, _newDepartment);
    }

    function deactivateCourse(string memory _courseId) external onlyVerifiedInstitution {
        require(courses[_courseId].creationDate > 0, "Course does not exist");
        require(courses[_courseId].isActive, "Course is already inactive");

        courses[_courseId].isActive = false;
        emit CourseDeactivated(_courseId);
    }

    function setCurrentActiveSemester(string memory _semester) external onlyVerifiedInstitution {
        require(bytes(_semester).length > 0, "Semester cannot be empty");
        string memory oldSemester = currentActiveSemester;
        currentActiveSemester = _semester;
        emit CurrentActiveSemesterUpdated(oldSemester, _semester);
    }

    function addCourseOffering(
        string memory _courseId,
        string memory _semester,
        string memory _doctorName,
        uint256 _examDate,
        string memory _bookTitle
    ) external onlyVerifiedInstitution {
        require(courses[_courseId].creationDate > 0, "Course does not exist");
        require(courses[_courseId].isActive, "Course is inactive");
        require(bytes(_semester).length > 0, "Semester cannot be empty");
        require(bytes(_doctorName).length > 0, "Doctor name cannot be empty");
        require(
            keccak256(abi.encodePacked(courseOfferings[_courseId][_semester].semester)) == keccak256(abi.encodePacked("")),
            "Course offering already exists for this semester"
        );

        courseOfferings[_courseId][_semester] = CourseOffering({
            semester: _semester,
            doctorName: _doctorName,
            examDate: _examDate,
            bookTitle: _bookTitle,
            isAvailableForEnrollment: true
        });

        // Check if semester exists in terms array
        bool semesterExists = false;
        for (uint i = 0; i < courseOfferingTerms[_courseId].length; i++) {
            if (keccak256(abi.encodePacked(courseOfferingTerms[_courseId][i])) == keccak256(abi.encodePacked(_semester))) {
                semesterExists = true;
                break;
            }
        }
        if (!semesterExists) {
            courseOfferingTerms[_courseId].push(_semester);
        }

        emit CourseOfferingAdded(_courseId, _semester, _doctorName);
    }

    // View Functions
    function isDepartmentExist(string memory _departmentName) public view returns (bool) {
        return departments[_departmentName];
    }

    function getAllDepartments() external view returns (string[] memory) {
        return departmentNames;
    }

    function getCourseStaticDetails(string memory _courseId)
        external
        view
        returns (
            string memory courseId,
            string memory name,
            uint256 credits,
            string memory department,
            bool isActive,
            uint256 creationDate
        )
    {
        Course memory course = courses[_courseId];
        return (
            course.courseId,
            course.name,
            course.credits,
            course.department,
            course.isActive,
            course.creationDate
        );
    }

    function getCourseOfferingDetails(string memory _courseId, string memory _semester)
        external
        view
        returns (
            string memory semester,
            string memory doctorName,
            uint256 examDate,
            string memory bookTitle,
            bool isAvailableForEnrollment
        )
    {
        CourseOffering memory offering = courseOfferings[_courseId][_semester];
        return (
            offering.semester,
            offering.doctorName,
            offering.examDate,
            offering.bookTitle,
            offering.isAvailableForEnrollment
        );
    }

    function getLatestCourseOfferingDetails(string memory _courseId)
        external
        view
        returns (
            string memory semester,
            string memory doctorName,
            uint256 examDate,
            string memory bookTitle,
            bool isAvailableForEnrollment
        )
    {
        CourseOffering memory offering = courseOfferings[_courseId][currentActiveSemester];
        return (
            offering.semester,
            offering.doctorName,
            offering.examDate,
            offering.bookTitle,
            offering.isAvailableForEnrollment
        );
    }

    function getAllCourseOfferingsForCourse(string memory _courseId)
        external
        view
        returns (CourseOffering[] memory)
    {
        string[] memory terms = courseOfferingTerms[_courseId];
        CourseOffering[] memory allOfferings = new CourseOffering[](terms.length);

        for (uint i = 0; i < terms.length; i++) {
            allOfferings[i] = courseOfferings[_courseId][terms[i]];
        }

        return allOfferings;
    }

    function getCoursesByDepartment(string memory _departmentName)
        external
        view
        returns (Course[] memory)
    {
        string[] memory deptCourses = departmentCourses[_departmentName];
        Course[] memory result = new Course[](deptCourses.length);

        for (uint i = 0; i < deptCourses.length; i++) {
            result[i] = courses[deptCourses[i]];
        }

        return result;
    }
}

contracts/Examinations.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./Identity.sol";

contract Examinations is ReentrancyGuard {
    Identity public identityContract;

    struct Examination {
        address institution;
        string ipfsHash;  // Contains exam details and questions
        uint256 startTime;
        uint256 endTime;
        bool isActive;
        mapping(address => bool) registeredStudents;
        mapping(address => string) studentAnswers;  // IPFS hash of student answers
        mapping(address => uint256) grades;
        mapping(address => bool) graded;
    }

    mapping(bytes32 => Examination) public examinations;
    mapping(address => bytes32[]) public institutionExams;
    mapping(address => bytes32[]) public studentExams;

    event ExaminationCreated(bytes32 indexed examId, address indexed institution);
    event StudentRegistered(bytes32 indexed examId, address indexed student);
    event AnswersSubmitted(bytes32 indexed examId, address indexed student);
    event GradeAssigned(bytes32 indexed examId, address indexed student, uint256 grade);

    constructor(address _identityContract) {
        identityContract = Identity(_identityContract);
    }

    modifier onlyVerifiedInstitution() {
        require(
            identityContract.getUserRole(msg.sender) == Identity.UserRole.INSTITUTION &&
            identityContract.isVerifiedUser(msg.sender),
            "Not a verified institution"
        );
        _;
    }

    modifier onlyVerifiedStudent() {
        require(
            identityContract.getUserRole(msg.sender) == Identity.UserRole.STUDENT &&
            identityContract.isVerifiedUser(msg.sender),
            "Not a verified student"
        );
        _;
    }

    function createExamination(
        string memory _ipfsHash,
        uint256 _startTime,
        uint256 _endTime
    ) external onlyVerifiedInstitution nonReentrant returns (bytes32) {
        require(_startTime > block.timestamp, "Invalid start time");
        require(_endTime > _startTime, "Invalid end time");

        bytes32 examId = keccak256(
            abi.encodePacked(msg.sender, _ipfsHash, _startTime, _endTime)
        );

        Examination storage exam = examinations[examId];
        exam.institution = msg.sender;
        exam.ipfsHash = _ipfsHash;
        exam.startTime = _startTime;
        exam.endTime = _endTime;
        exam.isActive = true;

        institutionExams[msg.sender].push(examId);

        emit ExaminationCreated(examId, msg.sender);

        return examId;
    }

    function registerForExam(bytes32 _examId) external onlyVerifiedStudent nonReentrant {
        Examination storage exam = examinations[_examId];
        require(exam.isActive, "Examination not active");
        require(block.timestamp < exam.startTime, "Registration period ended");
        require(!exam.registeredStudents[msg.sender], "Already registered");

        exam.registeredStudents[msg.sender] = true;
        studentExams[msg.sender].push(_examId);

        emit StudentRegistered(_examId, msg.sender);
    }

    function submitAnswers(
        bytes32 _examId,
        string memory _answersIpfsHash
    ) external onlyVerifiedStudent nonReentrant {
        Examination storage exam = examinations[_examId];
        require(exam.isActive, "Examination not active");
        require(exam.registeredStudents[msg.sender], "Not registered for exam");
        require(
            block.timestamp >= exam.startTime && block.timestamp <= exam.endTime,
            "Not within examination period"
        );

        exam.studentAnswers[msg.sender] = _answersIpfsHash;

        emit AnswersSubmitted(_examId, msg.sender);
    }

    function assignGrade(
        bytes32 _examId,
        address _student,
        uint256 _grade
    ) external onlyVerifiedInstitution nonReentrant {
        Examination storage exam = examinations[_examId];
        require(exam.institution == msg.sender, "Not examination creator");
        require(exam.registeredStudents[_student], "Student not registered");
        require(!exam.graded[_student], "Already graded");
        require(_grade <= 100, "Invalid grade");

        exam.grades[_student] = _grade;
        exam.graded[_student] = true;

        emit GradeAssigned(_examId, _student, _grade);
    }

    function getExamDetails(bytes32 _examId) external view returns (
        address institution,
        string memory ipfsHash,
        uint256 startTime,
        uint256 endTime,
        bool isActive
    ) {
        Examination storage exam = examinations[_examId];
        return (
            exam.institution,
            exam.ipfsHash,
            exam.startTime,
            exam.endTime,
            exam.isActive
        );
    }

    function getStudentGrade(bytes32 _examId, address _student) external view returns (
        uint256 grade,
        bool isGraded
    ) {
        Examination storage exam = examinations[_examId];
        return (exam.grades[_student], exam.graded[_student]);
    }
}

