// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

interface IIdentity {
    enum UserRole { NONE, STUDENT, INSTITUTION, EMPLOYER, ADMIN }

    function getUserRole(address _userAddress) external view returns (UserRole);
    function isVerifiedUser(address _userAddress) external view returns (bool);
    function userExists(address _userAddress) external view returns (bool);
    function isStudentEnrolled(address _institution, address _student) external view returns (bool);
}

contract ExamManagement is Ownable, Pausable {
    using Counters for Counters.Counter;

    IIdentity public identityContract;

    enum ExamStatus { UPCOMING, IN_PROGRESS, COMPLETED }

    struct Exam {
        address institution;      // Institution that created the exam
        string title;            // Exam title
        string description;      // Exam description
        uint256 date;           // Exam date in unix timestamp
        uint256 duration;       // Duration in minutes
        string ipfsHash;        // TODO: IPFS implementation will be added later for PDF file storage
        address[] students;     // Enrolled students
        bool exists;            // Whether the exam exists
        ExamStatus status;      // Exam status
    }

    struct ExamResult {
        uint256 score;
        string grade;
        string notes;
        bool exists;
    }

    // Mappings
    mapping(bytes32 => Exam) public exams;
    mapping(bytes32 => mapping(address => ExamResult)) public examResults;
    mapping(address => bytes32[]) public institutionExams;
    mapping(address => bytes32[]) public studentExams;

    // Counters
    Counters.Counter private _examIds;

    // Events
    // TODO: IPFS hash will be added to event later
    event ExamCreated(
        bytes32 indexed examId,
        address indexed institution,
        string title,
        string description,
        uint256 date,
        uint256 duration,
        ExamStatus status
    );
    event ExamUpdated(bytes32 indexed examId, string title, uint256 date, ExamStatus status);
    event StudentsRegistered(bytes32 indexed examId, address[] students);
    event ResultSubmitted(bytes32 indexed examId, address indexed student);

    constructor(address _identityContractAddress) {
        identityContract = IIdentity(_identityContractAddress);
    }

    /// @dev Computes the current exam status from time-based criteria.
    ///      This is the SINGLE source of truth for exam status.
    ///      The stored `exam.status` field is DEPRECATED and may be stale.
    /// @param exam The Exam struct stored in the exams mapping
    /// @return ExamStatus The current status based on block.timestamp
    function _getCurrentStatus(Exam memory exam) private view returns (ExamStatus) {
        if (block.timestamp < exam.date) {
            return ExamStatus.UPCOMING;
        } else if (block.timestamp < exam.date + exam.duration * 1 minutes) {
            return ExamStatus.IN_PROGRESS;
        } else {
            return ExamStatus.COMPLETED;
        }
    }

    // Modifiers
    modifier onlyVerifiedInstitution() {
        require(identityContract.getUserRole(msg.sender) == IIdentity.UserRole.INSTITUTION, "Not a registered institution");
        require(identityContract.isVerifiedUser(msg.sender), "Institution is not verified");
        _;
    }

    modifier onlyExistingExam(bytes32 examId) {
        require(exams[examId].exists, "Exam does not exist");
        _;
    }

    // Exam Management
    // TODO: IPFS parameter will be added later for PDF storage
    function createExam(
        string memory title,
        string memory description,
        uint256 examDate,
        uint256 duration
    ) external onlyVerifiedInstitution returns (bytes32) {
        _examIds.increment();
        bytes32 examId = keccak256(abi.encodePacked(_examIds.current(), msg.sender));

        // Determine initial status based on date
        ExamStatus initialStatus;
        if (examDate < block.timestamp) {
            revert("Exam date must be in the future");
        } else if (examDate == block.timestamp) {
            initialStatus = ExamStatus.IN_PROGRESS;
        } else {
            initialStatus = ExamStatus.UPCOMING;
        }

        exams[examId] = Exam({
            institution: msg.sender,
            title: title,
            description: description,
            date: examDate,
            duration: duration,
            ipfsHash: "", // TODO: Will be implemented later
            students: new address[](0),
            exists: true,
            status: initialStatus
        });

        institutionExams[msg.sender].push(examId);

        emit ExamCreated(
            examId,
            msg.sender,
            title,
            description,
            examDate,
            duration,
            initialStatus
        );
        return examId;
    }

    // TODO: Will add IPFS update functionality later
    function updateExam(
        bytes32 examId,
        string memory newTitle,
        string memory newDescription,
        uint256 newDate,
        uint256 newDuration,
        bool newExists
    ) external onlyVerifiedInstitution onlyExistingExam(examId) {
        Exam storage exam = exams[examId];
        exam.title = newTitle;
        exam.description = newDescription;
        exam.date = newDate;
        exam.duration = newDuration;
        exam.exists = newExists;

        // Update status based on new date
        if (newDate < block.timestamp) {
            exam.status = ExamStatus.COMPLETED;
        } else if (newDate == block.timestamp) {
            exam.status = ExamStatus.IN_PROGRESS;
        } else {
            exam.status = ExamStatus.UPCOMING;
        }

        emit ExamUpdated(examId, newTitle, newDate, exam.status);
    }

    function registerStudentsForExam(
        bytes32 examId,
        address[] memory studentAddresses
    ) external onlyVerifiedInstitution onlyExistingExam(examId) {
        require(studentAddresses.length > 0, "Student list cannot be empty");

        for (uint i = 0; i < studentAddresses.length; i++) {
            address studentAddress = studentAddresses[i];
            require(identityContract.userExists(studentAddress), "Student does not exist in Identity");
            require(identityContract.getUserRole(studentAddress) == IIdentity.UserRole.STUDENT, "User is not a student in Identity");
            require(identityContract.isStudentEnrolled(msg.sender, studentAddress), "Student is not enrolled in this institution");

            bool alreadyRegistered = false;
            for (uint j = 0; j < studentExams[studentAddress].length; j++) {
                if (studentExams[studentAddress][j] == examId) {
                    alreadyRegistered = true;
                    break;
                }
            }

            if (!alreadyRegistered) {
                studentExams[studentAddress].push(examId);
                exams[examId].students.push(studentAddress);
            } else {
                revert("Student already registered for this exam");
            }
        }

        emit StudentsRegistered(examId, studentAddresses);
    }

    // Result Management
    function submitResult(
        bytes32 examId,
        address student,
        uint256 score,
        string memory grade,
        string memory notes
    ) external onlyVerifiedInstitution onlyExistingExam(examId) {
        require(identityContract.isStudentEnrolled(msg.sender, student), "Student is not enrolled in this institution");


        examResults[examId][student] = ExamResult({
            score: score,
            grade: grade,
            notes: notes,
            exists: true
        });

        emit ResultSubmitted(examId, student);
    }

    function getExamResult(bytes32 examId, address student) external view returns (
        uint256 score,
        string memory grade,
        string memory notes
    ) {
        ExamResult memory result = examResults[examId][student];
        return (
            result.score,
            result.grade,
            result.notes
        );
    }

    function getExamStatistics(bytes32 examId) external view returns (
        uint256 totalStudents,
        uint256 passRate,
        uint256 averageScore
    ) {
        Exam memory exam = exams[examId];
        uint256 total = 0;
        uint256 passed = 0;
        uint256 scoreSum = 0;

        for (uint i = 0; i < exam.students.length; i++) {
            ExamResult memory result = examResults[examId][exam.students[i]];
            if (result.exists) {
                total++;
                scoreSum += result.score;
                if (result.score >= 60) {
                    passed++;
                }
            }
        }

        return (
            total,
            total > 0 ? (passed * 100) / total : 0,
            total > 0 ? scoreSum / total : 0
        );
    }

    function getUserExams(address user) external view returns (bytes32[] memory) {
        IIdentity.UserRole role = identityContract.getUserRole(user);

        if (role == IIdentity.UserRole.INSTITUTION) {
            return institutionExams[user];
        } else if (role == IIdentity.UserRole.STUDENT) {
            return studentExams[user];
        } else {
            revert("Unsupported role or user does not exist");
        }
    }

    function getStudentExamsWithStatus(address studentAddress) 
        external 
        view 
        returns (
            bytes32[] memory upcomingExams,
            bytes32[] memory inProgressExams,
            bytes32[] memory completedExams,
            ExamResult[] memory completedResults
        ) 
    {
        require(
            identityContract.getUserRole(studentAddress) == IIdentity.UserRole.STUDENT,
            "Address is not a student"
        );

        bytes32[] memory allExams = studentExams[studentAddress];

        // First count exams of each type
        uint256 upcomingCount = 0;
        uint256 inProgressCount = 0;
        uint256 completedCount = 0;

        for (uint i = 0; i < allExams.length; i++) {
            Exam memory exam = exams[allExams[i]];
            ExamStatus currentStatus = _getCurrentStatus(exam);
            if (currentStatus == ExamStatus.UPCOMING) {
                upcomingCount++;
            } else if (currentStatus == ExamStatus.IN_PROGRESS) {
                inProgressCount++;
            } else if (currentStatus == ExamStatus.COMPLETED) {
                completedCount++;
            }
        }

        // Initialize arrays with correct sizes
        upcomingExams = new bytes32[](upcomingCount);
        inProgressExams = new bytes32[](inProgressCount);
        completedExams = new bytes32[](completedCount);
        completedResults = new ExamResult[](completedCount);

        // Reset counters to use as indices
        upcomingCount = 0;
        inProgressCount = 0;
        completedCount = 0;

        // Fill arrays
        for (uint i = 0; i < allExams.length; i++) {
            bytes32 examId = allExams[i];
            Exam memory exam = exams[examId];
            ExamStatus currentStatus = _getCurrentStatus(exam);

            if (currentStatus == ExamStatus.UPCOMING) {
                upcomingExams[upcomingCount] = examId;
                upcomingCount++;
            } else if (currentStatus == ExamStatus.IN_PROGRESS) {
                inProgressExams[inProgressCount] = examId;
                inProgressCount++;
            } else if (currentStatus == ExamStatus.COMPLETED) {
                completedExams[completedCount] = examId;
                completedResults[completedCount] = examResults[examId][studentAddress];
                completedCount++;
            }
        }

        return (upcomingExams, inProgressExams, completedExams, completedResults);
    }

    function getExam(bytes32 examId) external view returns (Exam memory) {
        Exam memory exam = exams[examId];
        exam.status = _getCurrentStatus(exam);
        return exam;
    }
}

contracts/GraduationManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "./ICertificateValidator.sol";

// Minimal interfaces for external contracts
interface IIdentity {
    function getUserRole(address _userAddress) external view returns (uint8);
    function isVerifiedUser(address _userAddress) external view returns (bool);
    function isStudentEnrolled(address _institution, address _student) external view returns (bool);
}

interface IStudentAcademicManager {
    function getStudentGpa(address _student) external view returns (uint256);
    function getStudentTotalCredits(address _student) external view returns (uint256);
    function getStudentEnrolledCourses(address _student) external view returns (string[] memory);
    function getStudentEnrollment(
        address _student,
        string calldata courseId,
        string calldata semester
    ) external view returns (
        string memory,
        string memory,
        uint8,
        bool,
        uint256
    );
    function getStudentSemestersForCourse(
        address _student,
        string calldata courseId
    ) external view returns (string[] memory);
}

contract GraduationManager is Ownable, ReentrancyGuard, Pausable, ICertificateValidator {

    // ---------- Enums ----------

    enum GraduationStatus { NOT_ELIGIBLE, ELIGIBLE, APPROVED, GRADUATED }

    // ---------- Structs ----------

    struct GraduationRequirement {
        string department;
        uint256 minimumCredits;
        uint256 minimumGpa;
        string[] requiredCourseIds;
        bool thesisRequired;
        bool internshipRequired;
        uint256 eligibilityWindowDays;
        bool isActive;
    }

    struct GraduationRecord {
        GraduationStatus status;
        address enrollingInstitution;
        string department;
        uint256 eligibilityCheckDate;
        uint256 eligibilityExpiryDate;
        uint256 approvalDate;
        uint256 graduationDate;
        address approvedBy;
        bytes32 degreeCertificateId;
        string degreeType;
        bool degreeIssued;
        uint256 lastUpdateTimestamp;
    }

    // ---------- State ----------

    IIdentity public identityContract;
    IStudentAcademicManager public academicContract;

    mapping(address => GraduationStatus) public graduationStatus;
    mapping(address => GraduationRecord) public graduationRecords;
    mapping(address => mapping(bytes32 => GraduationRequirement)) public graduationRequirements;
    mapping(address => bool) public requirementsConfigured;
    mapping(address => address[]) public institutionGraduates;
    mapping(address => bytes32[]) public institutionDepartments;

    // ---------- Events ----------

    event RequirementsConfigured(
        address indexed institution,
        bytes32 indexed department,
        uint256 minimumCredits,
        uint256 minimumGpa,
        uint256 timestamp
    );

    event EligibilityAchieved(
        address indexed student,
        address indexed institution,
        bytes32 department,
        uint256 eligibilityExpiry,
        uint256 totalCredits,
        uint256 gpa,
        uint256 timestamp
    );

    event GraduationApproved(
        address indexed student,
        address indexed institution,
        bytes32 department,
        uint256 approvalDate,
        uint256 timestamp
    );

    event StudentGraduated(
        address indexed student,
        address indexed institution,
        bytes32 certificateId,
        string degreeType,
        uint256 graduationDate,
        uint256 timestamp
    );

    event AdminEmergencyStatusSet(
        address indexed student,
        GraduationStatus previousStatus,
        GraduationStatus newStatus,
        string reason,
        uint256 timestamp
    );

    // ---------- Modifiers ----------

    modifier onlyVerifiedInstitution() {
        require(
            identityContract.isVerifiedUser(msg.sender) &&
            identityContract.getUserRole(msg.sender) == 2, // INSTITUTION = 2
            "Not a verified institution"
        );
        _;
    }

    modifier onlyEnrolledInstitution(address student) {
        require(
            identityContract.isStudentEnrolled(msg.sender, student),
            "Not the enrolling institution"
        );
        _;
    }

    // ---------- Constructor ----------

    constructor(
        address _identityContract,
        address _academicContract
    ) Ownable() {
        require(_identityContract != address(0), "Identity contract cannot be zero address");
        require(_academicContract != address(0), "Academic contract cannot be zero address");

        identityContract = IIdentity(_identityContract);
        academicContract = IStudentAcademicManager(_academicContract);
    }

    // -------------------------------------------------------
    //  REQUIREMENTS CONFIGURATION
    // -------------------------------------------------------

    function setRequirements(
        string calldata department,
        uint256 minimumCredits,
        uint256 minimumGpa,
        string[] calldata requiredCourseIds,
        bool thesisRequired,
        bool internshipRequired,
        uint256 eligibilityWindowDays
    ) external onlyVerifiedInstitution {
        address institution = msg.sender;
        bytes32 deptKey = keccak256(abi.encodePacked(department));

        graduationRequirements[institution][deptKey] = GraduationRequirement({
            department: department,
            minimumCredits: minimumCredits,
            minimumGpa: minimumGpa,
            requiredCourseIds: requiredCourseIds,
            thesisRequired: thesisRequired,
            internshipRequired: internshipRequired,
            eligibilityWindowDays: eligibilityWindowDays,
            isActive: true
        });

        requirementsConfigured[institution] = true;

        // Track department for this institution
        bytes32[] storage depts = institutionDepartments[institution];
        bool deptFound = false;
        for (uint i = 0; i < depts.length; i++) {
            if (depts[i] == deptKey) {
                deptFound = true;
                break;
            }
        }
        if (!deptFound) {
            depts.push(deptKey);
        }

        emit RequirementsConfigured(institution, deptKey, minimumCredits, minimumGpa, block.timestamp);
    }

    // -------------------------------------------------------
    //  INTERNAL HELPERS
    // -------------------------------------------------------

    function _isCourseCompleted(address student, string memory courseId) internal view returns (bool) {
        string[] memory semesters = academicContract.getStudentSemestersForCourse(student, courseId);
        for (uint i = 0; i < semesters.length; i++) {
            (, , , bool completed, ) = academicContract.getStudentEnrollment(student, courseId, semesters[i]);
            if (completed) {
                return true;
            }
        }
        return false;
    }

    function _isCourseIdMatch(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(abi.encodePacked(a)) == keccak256(abi.encodePacked(b));
    }

    // -------------------------------------------------------
    //  ELIGIBILITY CHECK
    // -------------------------------------------------------

    function checkEligibility(
        address student,
        bytes32 departmentKey
    ) external onlyVerifiedInstitution onlyEnrolledInstitution(student) {
        address institution = msg.sender;
        require(requirementsConfigured[institution], "Requirements not configured");

        GraduationRequirement memory reqs = graduationRequirements[institution][departmentKey];
        require(reqs.isActive, "Requirements not active");

        require(uint256(graduationStatus[student]) == 0, "Invalid status for eligibility check");

        uint256 studentGpa = academicContract.getStudentGpa(student);
        uint256 studentCredits = academicContract.getStudentTotalCredits(student);
        bool isEligible = true;

        if (reqs.minimumCredits > 0 && studentCredits < reqs.minimumCredits) {
            isEligible = false;
        }

        if (isEligible && reqs.minimumGpa > 0 && studentGpa < reqs.minimumGpa) {
            isEligible = false;
        }

        if (isEligible && reqs.requiredCourseIds.length > 0) {
            isEligible = _checkRequiredCourses(student, reqs.requiredCourseIds);
        }

        if (isEligible) {
            uint256 expiry = 0;
            if (reqs.eligibilityWindowDays > 0) {
                expiry = block.timestamp + reqs.eligibilityWindowDays * 1 days;
            }

            graduationStatus[student] = GraduationStatus.ELIGIBLE;
            graduationRecords[student] = GraduationRecord({
                status: GraduationStatus.ELIGIBLE,
                enrollingInstitution: institution,
                department: reqs.department,
                eligibilityCheckDate: block.timestamp,
                eligibilityExpiryDate: expiry,
                approvalDate: 0,
                graduationDate: 0,
                approvedBy: address(0),
                degreeCertificateId: bytes32(0),
                degreeType: "",
                degreeIssued: false,
                lastUpdateTimestamp: block.timestamp
            });

            emit EligibilityAchieved(
                student, institution, departmentKey, expiry,
                studentCredits, studentGpa, block.timestamp
            );
        }
    }

    function _checkRequiredCourses(address student, string[] memory required) internal view returns (bool) {
        string[] memory enrolled = academicContract.getStudentEnrolledCourses(student);
        for (uint i = 0; i < required.length; i++) {
            bool found = false;
            for (uint j = 0; j < enrolled.length; j++) {
                if (_isCourseIdMatch(required[i], enrolled[j])) {
                    if (_isCourseCompleted(student, enrolled[j])) {
                        found = true;
                    }
                    break;
                }
            }
            if (!found) {
                return false;
            }
        }
        return true;
    }

    // -------------------------------------------------------
    //  GRADUATION APPROVAL
    // -------------------------------------------------------

    function approveGraduation(address student) external onlyVerifiedInstitution onlyEnrolledInstitution(student) {
        require(
            graduationStatus[student] == GraduationStatus.ELIGIBLE,
            "Student is not eligible"
        );

        GraduationRecord storage record = graduationRecords[student];

        if (record.eligibilityExpiryDate > 0) {
            require(block.timestamp <= record.eligibilityExpiryDate, "Eligibility expired");
        }

        record.status = GraduationStatus.APPROVED;
        record.approvalDate = block.timestamp;
        record.approvedBy = msg.sender;
        record.lastUpdateTimestamp = block.timestamp;
        graduationStatus[student] = GraduationStatus.APPROVED;

        emit GraduationApproved(
            student, msg.sender,
            keccak256(abi.encodePacked(record.department)),
            block.timestamp, block.timestamp
        );
    }

    // -------------------------------------------------------
    //  FINALIZE GRADUATION (after Certificates issue)
    // -------------------------------------------------------

    function finalizeGraduation(
        address student,
        bytes32 certificateId,
        string calldata degreeType
    ) external onlyVerifiedInstitution onlyEnrolledInstitution(student) {
        require(
            graduationStatus[student] == GraduationStatus.APPROVED,
            "Graduation not approved"
        );

        GraduationRecord storage record = graduationRecords[student];
        require(!record.degreeIssued, "Degree already issued");
        require(record.approvedBy == msg.sender, "Not the approving institution");

        record.status = GraduationStatus.GRADUATED;
        record.graduationDate = block.timestamp;
        record.degreeCertificateId = certificateId;
        record.degreeType = degreeType;
        record.degreeIssued = true;
        record.lastUpdateTimestamp = block.timestamp;
        graduationStatus[student] = GraduationStatus.GRADUATED;

        institutionGraduates[msg.sender].push(student);

        emit StudentGraduated(
            student, msg.sender, certificateId,
            degreeType, block.timestamp, block.timestamp
        );
    }

    // -------------------------------------------------------
    //  CERTIFICATE VALIDATION HOOK (ICertificateValidator)
    // -------------------------------------------------------

    function validateIssuance(
        address institution,
        address student,
        string calldata
    ) external view override returns (bool allowed, string memory reason) {
        if (graduationStatus[student] != GraduationStatus.APPROVED) {
            return (false, "Graduation not approved");
        }

        GraduationRecord memory record = graduationRecords[student];
        if (record.approvedBy != institution) {
            return (false, "Not the approving institution");
        }

        if (!identityContract.isStudentEnrolled(institution, student)) {
            return (false, "Not the enrolling institution");
        }

        return (true, "");
    }

    // -------------------------------------------------------
    //  VIEW FUNCTIONS
    // -------------------------------------------------------

    function getGraduationStatus(address student) external view returns (GraduationStatus) {
        return graduationStatus[student];
    }

    function getGraduationRecord(address student) external view returns (GraduationRecord memory) {
        return graduationRecords[student];
    }

    function getGraduationRequirements(address institution, bytes32 department) external view returns (GraduationRequirement memory) {
        return graduationRequirements[institution][department];
    }

    function getInstitutionGraduates(address institution) external view returns (address[] memory) {
        return institutionGraduates[institution];
    }

    // -------------------------------------------------------
    //  ADMIN EMERGENCY OVERRIDE
    // -------------------------------------------------------

    function adminSetGraduationStatus(
        address student,
        GraduationStatus newStatus,
        string calldata reason
    ) external onlyOwner {
        GraduationStatus previousStatus = graduationStatus[student];
        graduationStatus[student] = newStatus;
        graduationRecords[student].status = newStatus;
        graduationRecords[student].lastUpdateTimestamp = block.timestamp;

        emit AdminEmergencyStatusSet(student, previousStatus, newStatus, reason, block.timestamp);
    }
}

